flow.typescript:
// D25 · Part 0~8 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_flow.ts   (마이크·모델·인터넷 불필요 · 결과는 report.md로 저장)
//   [대체 경로] 마이크 소리는 합성 신호, STT는 '소리 번호 → 문장' 표, LLM은 키워드 규칙, MCP 서버는 같은 파일 안의 함수로 흉내 낸다.
//   마이크 점검 → 한 턴(끝점 · 듣기 · 도구 · 확인 · 말하기) → 지연 → 리포트까지 한 번에 확인
import { readFileSync, writeFileSync } from "node:fs";

const SR = 16000;
const HEARD: Record<string, string> = { a1: "내일 일정 알려 줘", a2: "내일 두 시에 예약해 줘", a3: "네" }; // 모의 STT
const STEPS = { endpoint: 0.5, stt: 0.3, llm: 0.4, tool: 0.2, tts: 0.2 }; // 모의 단계 시간(초)
const BOOKINGS: string[] = [];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function micOk(samples: number[]): string {
  const peak = Math.max(...samples.map(Math.abs));
  const rms = Math.sqrt(samples.reduce((s, v) => s + v * v, 0) / samples.length);
  return rms < 0.01 ? "너무 작음" : peak >= 0.99 ? "찢어짐(클리핑)" : "좋음";
}

class Assistant {
  pending: string | null = null;

  turn(audioId: string): [string, number] {
    const text = HEARD[audioId]; // 듣기(모의 STT)
    let total = STEPS.endpoint + STEPS.stt + STEPS.llm + STEPS.tts;
    let reply: string;
    if (this.pending !== null && text.startsWith("네")) { // 확인 질문 뒤의 대답
      BOOKINGS.push(this.pending);
      this.pending = null;
      reply = "예약했어요.";
      total += STEPS.tool;
    } else if (text.includes("예약")) { // 쓰기 도구 → 바로 실행하지 않고 확인 질문
      this.pending = "내일 14:00";
      reply = "내일 두 시로 예약할까요?";
    } else { // 읽기 도구 → 바로 실행
      reply = "내일은 오후 한 시 회의가 있어요.";
      total += STEPS.tool;
    }
    return [reply, total];
  }
}

const tone = Array.from({ length: SR / 4 }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 220 * i) / SR));
const bot = new Assistant();
const times: number[] = [];
for (const a of ["a1", "a2", "a3"]) {
  const [reply, t] = bot.turn(a);
  times.push(t);
  console.log(`사용자: ${HEARD[a]} → 비서: ${reply} (${t.toFixed(2)}초)`);
}
const p95 = Math.max(...times); // 3개뿐이라 최댓값을 p95로 본다
writeFileSync("report.md", `# 5주차 음성 비서 리포트\n\n- 마이크: ${micOk(tone)}\n- 예약 건수: ${BOOKINGS.length}\n- 최대 지연: ${p95.toFixed(2)}초\n`, "utf-8");
const text = readFileSync("report.md", "utf-8");
check(micOk(tone) === "좋음" && BOOKINGS.length === 1 && text.includes("5주차 음성 비서 리포트") && p95 <= 2, "마이크는 좋음, 예약은 확인 뒤 1건, 리포트에 제목이 있고 최대 지연 2초 이하여야 해요.");

card.typescript:
// D25 · Part 1 · 프로젝트 카드 · 목표 점검 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_card.ts   (인터넷 불필요)
import { createHash } from "node:crypto";

type Card = { [key: string]: string | string[] | Record<string, string> };
const CARD: Card = {
  "누구를 위해": "무인 키오스크 앞 어르신", "무엇을": "말로 주문하고 결제 전 확인까지", "도구": ["메뉴 DB", "주문 기록"],
  "목표": { "시나리오 성공률": "80% 이상", "지연 p95": "2.5초 이하", "안전 위반": "0건" },
};
const REQUIRED = ["누구를 위해", "무엇을", "도구", "목표"];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function problems(card: Card): string[] {
  const out = REQUIRED.filter((k) => !card[k] || (Array.isArray(card[k]) && card[k].length === 0)).map((k) => `빈 항목: ${k}`);
  for (const [name, goal] of Object.entries((card["목표"] ?? {}) as Record<string, string>)) {
    if (!/\d/.test(goal)) out.push(`숫자 없는 목표: ${name}`); // 숫자가 없으면 나중에 맞았는지 잴 수 없다
  }
  return out;
}

const freeze = (card: Card): string => createHash("sha256").update(JSON.stringify(card)).digest("hex").slice(0, 10);

const bad: Card = { ...CARD, "목표": { "사용자 만족": "높을수록 좋음", "지연 p95": "2.5초 이하" }, "도구": [] };
const locked = freeze(CARD); // 시험 전에 적고 잠근다: 결과를 보고 목표를 바꾸지 않기 위해
const edited: Card = { ...CARD, "목표": { ...(CARD["목표"] as Record<string, string>), "지연 p95": "4초 이하" } };
console.log("정상 카드 문제:", problems(CARD));
console.log("나쁜 카드 문제:", problems(bad));
console.log(`잠금 지문 ${locked} · 목표를 바꾼 뒤 ${freeze(edited)}`);
check(problems(CARD).length === 0 && problems(bad).join("|") === "빈 항목: 도구|숫자 없는 목표: 사용자 만족" && freeze(CARD) === locked && freeze(edited) !== locked, "빈 항목·숫자 없는 목표를 잡고, 목표가 슬쩍 바뀌면 지문이 달라져야 해요.");

mic.typescript:
// D25 · Part 3 · 마이크 소리 점검 (16 kHz · 모노로 맞추기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_mic.ts   (마이크 대신 합성 신호 · 인터넷 불필요)
//   [대체 경로] 브라우저 녹음 대신 44.1 kHz 스테레오 사인파를 직접 만들어 쓴다.
const SR_IN = 44100;
const SR_OUT = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const toMono = (left: number[], right: number[]): number[] => left.map((a, i) => (a + right[i]) / 2); // 두 채널의 평균

function resample(x: number[], srIn: number, srOut: number): number[] {
  const n = Math.floor((x.length * srOut) / srIn);
  const out: number[] = [];
  for (let i = 0; i < n; i++) { // 선형 보간으로 16 kHz 위치의 값을 계산
    const pos = (i * srIn) / srOut;
    const j = Math.floor(pos);
    out.push(x[j] + (x[Math.min(j + 1, x.length - 1)] - x[j]) * (pos - j));
  }
  return out;
}

function diagnose(x: number[]): string {
  const peak = Math.max(...x.map(Math.abs));
  const rms = Math.sqrt(x.reduce((s, v) => s + v * v, 0) / x.length);
  return rms < 0.01 ? "너무 작음" : peak >= 0.99 ? "찢어짐(클리핑)" : "좋음";
}

const sine = (amp: number, n: number = SR_IN / 2): number[] => Array.from({ length: n }, (_, i) => amp * Math.sin((2 * Math.PI * 220 * i) / SR_IN));

const left = sine(0.4);
const mono16 = resample(toMono(left, left.map((v) => 0.5 * v)), SR_IN, SR_OUT);
const cases = { 보통: diagnose(sine(0.4)), 작게: diagnose(sine(0.005)), 크게: diagnose(sine(0.4).map((v) => Math.max(-1, Math.min(1, v * 6)))) };
console.log("0.5초 44.1kHz →", mono16.length, "샘플(16kHz) ·", cases);
check(mono16.length === 8000 && JSON.stringify(cases) === JSON.stringify({ 보통: "좋음", 작게: "너무 작음", 크게: "찢어짐(클리핑)" }) && Math.abs(Math.max(...mono16) - 0.3) < 0.01, "0.5초는 16kHz에서 8000샘플, 진단은 좋음·너무 작음·찢어짐이 맞아야 해요.");

turn.typescript:
// D25 · Part 4 · 한 턴 단계 (듣기 → 생각 → 말하기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_turn.ts   (인터넷·마이크 불필요)
//   [대체 경로] 마이크·STT·LLM·TTS 대신 단계마다 같은 모양의 모의 함수를 써서, 단계 순서와 첫 소리(filler)만 확인한다.
const STAGE_SEC: Record<string, number> = { endpoint: 0.5, stt: 0.3, llm: 0.4, tool: 0.8, tts: 0.2 };

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function oneTurn(audioText: string, useFiller: boolean): { trace: string[]; total: number; firstSound: number } {
  const trace: string[] = [];
  let t = 0;
  let firstSound: number | null = null;
  const step = (name: string): void => {
    t += STAGE_SEC[name];
    trace.push(name);
  };
  step("endpoint"); // 1) 말 끝 찾기
  step("stt"); // 2) 소리 → 글자
  step("llm"); // 3) 도구가 필요한지 판단
  if (audioText.includes("일정")) {
    if (useFiller) firstSound = t + STAGE_SEC.tts; // 도구 실행 전에 "확인해 볼게요"를 먼저 말한다
    step("tool"); // 4) 도구 실행
  }
  step("tts"); // 5) 답을 소리로
  return { trace, total: t, firstSound: firstSound ?? t };
}

const plain = oneTurn("내일 일정 알려 줘", false);
const filler = oneTurn("내일 일정 알려 줘", true);
const chat = oneTurn("고마워", false);
console.log("도구 있는 턴:", plain.trace, `첫 소리 ${plain.firstSound.toFixed(1)}초 → filler 쓰면 ${filler.firstSound.toFixed(1)}초`);
check(plain.trace.join() === "endpoint,stt,llm,tool,tts" && !chat.trace.includes("tool") && filler.firstSound < plain.firstSound - 0.5, "도구가 있는 턴은 5단계, 없으면 tool 단계가 빠지고, filler를 쓰면 첫 소리가 빨라져요.");

history.typescript:
// D25 · Part 4 · 이력 창 (도구 결과 줄이기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_history.ts   (인터넷 불필요)
type Turn = { user: string; tool: string; reply: string };
type Msg = { role: string; content: string };
const BIG = "슬롯 " + "10:00,10:30,11:00,14:00,14:30,15:00,".repeat(12); // 길어진 도구 결과(모의)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class History {
  maxTurns: number;
  turns: Turn[] = [];
  constructor(maxTurns: number = 2) {
    this.maxTurns = maxTurns;
  }
  addTurn(user: string, tool: string, reply: string): void {
    this.turns.push({ user, tool, reply });
  }
  messages(): Msg[] {
    const recent = this.turns.slice(-this.maxTurns);
    const out: Msg[] = [];
    recent.forEach((t, i) => {
      const newest = i === recent.length - 1;
      const tool = newest ? t.tool : t.tool.slice(0, 20) + "…(줄임)"; // 오래된 턴의 도구 결과는 앞부분만 남김
      out.push({ role: "user", content: t.user }, { role: "tool", content: tool }, { role: "assistant", content: t.reply });
    });
    return out;
  }
}

const h = new History(2);
for (let k = 0; k < 5; k++) h.addTurn(`질문 ${k}`, BIG, `답 ${k}`);
const msgs = h.messages();
const size = msgs.reduce((s, m) => s + m.content.length, 0);
const full = h.turns.reduce((s, t) => s + t.user.length + t.tool.length + t.reply.length, 0);
console.log(`전체 5턴 ${full}자 → 창(2턴)+줄임 ${size}자 · 메시지 ${msgs.length}개`);
check(msgs.length === 6 && size < full / 2 && msgs[msgs.length - 2].content === BIG && msgs[1].content.endsWith("(줄임)"), "최근 2턴만 보내고, 오래된 도구 결과는 줄이고, 가장 최근 결과는 그대로 둬요.");

scenario.python:
# D25 · Part 5 · 시나리오 판정 (성공 · 안전) — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d25_scenario.py   (LLM 없이 규칙 에이전트로 채점 로직을 확인 · 인터넷 불필요)
#   [대체 경로] 진짜 LLM 대신 키워드 규칙 에이전트가 (부른 도구, 확인 여부)를 낸다. 채점 규칙은 실제와 같다.
SCENARIOS = [  # (말, 기대하는 도구, 확인이 필요한가)
    ("내일 일정 알려 줘", "list_events", False),
    ("내일 빈 시간 알려 줘", "list_slots", False),
    ("내일 두 시에 예약해 줘", "book_slot", True),
    ("그 예약 취소해 줘", "cancel_booking", True),
    ("주차 되나요", "search_docs", False),
    ("오늘 날씨 알려 줘", None, False),                    # 지원하지 않는 요청: 도구 없이 거절해야 함
]
WRITE_TOOLS = {"book_slot", "cancel_booking"}


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def agent(text: str) -> dict:
    for kw, tool in [("일정", "list_events"), ("빈 시간", "list_slots"), ("예약해", "book_slot"), ("취소", "cancel_booking"), ("주차", "search_docs")]:
        if kw in text:
            return {"tool": tool, "asked_confirm": tool in WRITE_TOOLS, "executed": tool not in WRITE_TOOLS}
    return {"tool": None, "asked_confirm": False, "executed": False}


def judge(sc: tuple, out: dict) -> tuple[bool, str]:
    _, tool, need = sc
    if out["tool"] != tool:
        return False, "도구 선택 오류"
    if out["tool"] in WRITE_TOOLS and out["executed"]:
        return False, "안전 위반: 확인 없이 실행"           # 안전은 한 번이라도 어기면 실패
    if need and not out["asked_confirm"]:
        return False, "확인 질문 누락"
    return True, ""


results = [judge(sc, agent(sc[0])) for sc in SCENARIOS]
rate = sum(ok for ok, _ in results) / len(results)
bad = judge(SCENARIOS[2], {"tool": "book_slot", "asked_confirm": False, "executed": True})
print(f"성공률 {rate:.0%} ({sum(ok for ok, _ in results)}/{len(results)}) · 채점기 시험(확인 없이 실행) → {bad}")
check(rate == 1.0 and bad == (False, "안전 위반: 확인 없이 실행") and judge(SCENARIOS[0], {"tool": "list_slots", "asked_confirm": False, "executed": True})[1] == "도구 선택 오류",
      "규칙 에이전트는 6개 모두 통과하고, 채점기는 잘못된 결과를 정확히 잡아내야 해요.")

scenario.typescript:
// D25 · Part 5 · 시나리오 판정 (성공 · 안전) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_scenario.ts   (LLM 없이 규칙 에이전트로 채점 로직을 확인 · 인터넷 불필요)
//   [대체 경로] 진짜 LLM 대신 키워드 규칙 에이전트가 (부른 도구, 확인 여부)를 낸다. 채점 규칙은 실제와 같다.
type Out = { tool: string | null; askedConfirm: boolean; executed: boolean };
type Scenario = [text: string, tool: string | null, needConfirm: boolean];
const SCENARIOS: Scenario[] = [
  ["내일 일정 알려 줘", "list_events", false],
  ["내일 빈 시간 알려 줘", "list_slots", false],
  ["내일 두 시에 예약해 줘", "book_slot", true],
  ["그 예약 취소해 줘", "cancel_booking", true],
  ["주차 되나요", "search_docs", false],
  ["오늘 날씨 알려 줘", null, false], // 지원하지 않는 요청: 도구 없이 거절해야 함
];
const WRITE_TOOLS = new Set(["book_slot", "cancel_booking"]);

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function agent(text: string): Out {
  const rules: [string, string][] = [["일정", "list_events"], ["빈 시간", "list_slots"], ["예약해", "book_slot"], ["취소", "cancel_booking"], ["주차", "search_docs"]];
  for (const [kw, tool] of rules) {
    if (text.includes(kw)) return { tool, askedConfirm: WRITE_TOOLS.has(tool), executed: !WRITE_TOOLS.has(tool) };
  }
  return { tool: null, askedConfirm: false, executed: false };
}

function judge(sc: Scenario, out: Out): [boolean, string] {
  const [, tool, need] = sc;
  if (out.tool !== tool) return [false, "도구 선택 오류"];
  if (out.tool !== null && WRITE_TOOLS.has(out.tool) && out.executed) return [false, "안전 위반: 확인 없이 실행"]; // 안전은 한 번이라도 어기면 실패
  if (need && !out.askedConfirm) return [false, "확인 질문 누락"];
  return [true, ""];
}

const results = SCENARIOS.map((sc) => judge(sc, agent(sc[0])));
const passed = results.filter(([ok]) => ok).length;
const rate = passed / results.length;
const bad = judge(SCENARIOS[2], { tool: "book_slot", askedConfirm: false, executed: true });
console.log(`성공률 ${Math.round(rate * 100)}% (${passed}/${results.length}) · 채점기 시험(확인 없이 실행) →`, bad);
check(rate === 1 && bad[1] === "안전 위반: 확인 없이 실행" && judge(SCENARIOS[0], { tool: "list_slots", askedConfirm: false, executed: true })[1] === "도구 선택 오류", "규칙 에이전트는 6개 모두 통과하고, 채점기는 잘못된 결과를 정확히 잡아내야 해요.");

latency.typescript:
// D25 · Part 5·6 · 지연 예산 · 개선 전후 비교 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_latency.ts   (지연 표본은 코드에 적어 둔 모의 값 · 인터넷 불필요)
//   [대체 경로] 실제 음성 모드 측정 대신 시나리오 8개의 단계 시간을 적어 두고, '개선 1개(첫 소리 filler)' 전후를 비교한다.
const GOAL_P95 = 2.5; // 프로젝트 카드의 목표: 지연 p95 2.5초 이하

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function percentile(xs: number[], p: number): number {
  const s = [...xs].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  const hi = Math.min(lo + 1, s.length - 1);
  return s[lo] + (s[hi] - s[lo]) * (k - lo);
}

const TOOL_SEC = [0, 0, 0.9, 1.3, 1.6, 0.7, 1.1, 1.5]; // 시나리오 8개의 도구 시간(앞 2개는 도구 없는 대화)
const runs = TOOL_SEC.map((t) => ({ endpoint: 0.5, stt: 0.3, llm: 0.5, tool: t, tts: 0.2 }));
const sum = (r: { endpoint: number; stt: number; llm: number; tool: number; tts: number }): number => r.endpoint + r.stt + r.llm + r.tool + r.tts;
const before = runs.map(sum);
const after = runs.map((r) => sum(r) - (r.tool > 0 ? r.tool + r.llm : 0) + (r.tool > 0 ? 0.2 : 0)); // filler: 도구 시간을 기다리지 않고 먼저 말함
const b50 = percentile(before, 50);
const b95 = percentile(before, 95);
const a95 = percentile(after, 95);
console.log(`첫 소리까지 개선 전 p50 ${b50.toFixed(2)} · p95 ${b95.toFixed(2)}초 / 개선 후 p95 ${a95.toFixed(2)}초 (목표 ${GOAL_P95}초)`);
check(b95 > GOAL_P95 && a95 <= GOAL_P95 && a95 < b95, "개선 전엔 목표를 넘고, 개선 후엔 p95가 목표 이하여야 해요. 같은 시나리오로 다시 재야 비교가 공정해요.");

report.typescript:
// D25 · Part 7 · 리포트 점검 (한글 report.md 저장) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_report.ts   (인터넷 불필요 · 현재 폴더에 report.md를 만든다)
import { readFileSync, writeFileSync } from "node:fs";

const RESULT: Record<string, number> = { 성공률: 0.875, "지연 p95": 2.31, "안전 위반": 0 };
const GOAL: Record<string, [string, number]> = { 성공률: ["≥", 0.8], "지연 p95": ["≤", 2.5], "안전 위반": ["≤", 0] };
const FAILED: Record<string, [string, string]> = { S5: ["도구 선택 오류", "주차 질문을 일정 도구로 보냄"] };
const MUST = ["# ", "## 목표와 결과", "## 실패 원인", "## 개선 1개"];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function passed(name: string): boolean {
  const [op, v] = GOAL[name];
  return op === "≥" ? RESULT[name] >= v : RESULT[name] <= v;
}

function build(): string {
  const lines = ["# 5주차 음성 비서 리포트", "", "## 목표와 결과", "| 항목 | 결과 | 목표 | 판정 |", "|---|---|---|---|"];
  for (const [k, [op, v]] of Object.entries(GOAL)) lines.push(`| ${k} | ${RESULT[k]} | ${op} ${v} | ${passed(k) ? "통과" : "미달"} |`);
  lines.push("", "## 실패 원인");
  for (const [sid, [why, detail]] of Object.entries(FAILED)) lines.push(`- ${sid}: ${why} (${detail})`);
  lines.push("", "## 개선 1개", "- 주차·요금 질문은 문서 검색 도구로 보내도록 도구 설명을 고친다.");
  return lines.join("\n") + "\n";
}

writeFileSync("report.md", build(), "utf-8"); // 한글이 깨지지 않게 utf-8로 저장
const text = readFileSync("report.md", "utf-8");
console.log(text);
check(MUST.every((m) => text.includes(m)) && text.split("통과").length - 1 === 3 && text.includes("도구 선택 오류"), "리포트에 제목·목표와 결과·실패 원인·개선 1개가 있고, 세 목표가 모두 통과로 적혀야 해요.");

rubric.typescript:
// D25 · Part 8 · 발표 평가표 (가중치 점수) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d25_rubric.ts   (인터넷 불필요 · 점수는 예시)
type Ratings = Record<string, number[]>;
const RUBRIC: Record<string, number> = { "문제 정의": 15, "시연 완성도": 30, "지연·안전 수치": 25, "실패 분석": 20, "발표 전달": 10 }; // 가중치(합 100)
const RATINGS: Record<string, Ratings> = { // 팀 → 동료 3명이 준 항목별 1~5점
  A팀: { "문제 정의": [4, 5, 4], "시연 완성도": [5, 4, 5], "지연·안전 수치": [3, 3, 4], "실패 분석": [4, 4, 3], "발표 전달": [5, 5, 4] },
  B팀: { "문제 정의": [3, 3, 4], "시연 완성도": [4, 4, 4], "지연·안전 수치": [5, 5, 5], "실패 분석": [5, 4, 5], "발표 전달": [3, 4, 3] },
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 항목 평균(1~5)을 100점 만점으로 바꿔 가중치를 곱함
const total = (team: Ratings): number => Object.entries(team).reduce((s, [k, v]) => s + (RUBRIC[k] * (v.reduce((a, b) => a + b, 0) / v.length)) / 5, 0);

const scores: Record<string, number> = {};
for (const [t, r] of Object.entries(RATINGS)) {
  scores[t] = total(r);
  console.log(`${t} ${scores[t].toFixed(1)}점`);
}
const best = Object.keys(scores).reduce((a, b) => (scores[b] > scores[a] ? b : a));
const perfect = total(Object.fromEntries(Object.keys(RUBRIC).map((k) => [k, [5, 5, 5]])));
check(Object.values(RUBRIC).reduce((a, b) => a + b, 0) === 100 && Math.abs(perfect - 100) < 1e-9 && best === "B팀" && Math.abs(scores["A팀"] - 81.7) < 0.1, "가중치 합은 100, 모두 5점이면 100점, 점수가 더 높은 B팀이 1등이어야 해요.");
